    },
    /**
    * 取消所有单元格的可以编辑状态
    */
    cancelCellEditable: function cancelCellEditable() {
      var self = this;
      if (self.taskComments && self.taskComments.length !== 0) {
        self.taskComments.forEach(function (item) {
          Vue.set(item, 'fullMessageEditable', false);
        });
      }
    },
